/**
 * Browser-side language switcher for next-i18n-auto
 * This module handles runtime language switching by updating DOM elements with data-i18n attributes
 */

export interface LanguageSwitcherOptions {
  localesPath?: string;
  defaultLanguage?: string;
  storageKey?: string;
}

export class LanguageSwitcher {
  private currentLanguage: string;
  private translations: Map<string, Record<string, string>>;
  private localesPath: string;
  private storageKey: string;

  constructor(options: LanguageSwitcherOptions = {}) {
    this.localesPath = options.localesPath || '/locales';
    this.storageKey = options.storageKey || 'i18n-language';
    this.translations = new Map();

    // Load saved language or use default
    this.currentLanguage = this.getSavedLanguage() || options.defaultLanguage || 'en';
  }

  /**
   * Get saved language from localStorage
   */
  private getSavedLanguage(): string | null {
    if (typeof window === 'undefined') return null;
    try {
      return localStorage.getItem(this.storageKey);
    } catch {
      return null;
    }
  }

  /**
   * Save language to localStorage
   */
  private saveLanguage(language: string): void {
    if (typeof window === 'undefined') return;
    try {
      localStorage.setItem(this.storageKey, language);
    } catch {
      // Ignore storage errors
    }
  }

  /**
   * Load translations for a specific language
   */
  async loadLanguage(language: string): Promise<void> {
    if (this.translations.has(language)) {
      return; // Already loaded
    }

    try {
      const response = await fetch(`${this.localesPath}/${language}.json`);

      if (!response.ok) {
        throw new Error(`Failed to load language: ${language}`);
      }

      const translations = await response.json();
      this.translations.set(language, translations);
    } catch (error) {
      console.error(`Error loading language ${language}:`, error);
      throw error;
    }
  }

  /**
   * Update all DOM elements with translated text
   */
  private updateDOM(language: string): void {
    const translations = this.translations.get(language);
    if (!translations) return;

    // Find all elements with data-i18n attribute
    const elements = document.querySelectorAll('[data-i18n]');

    elements.forEach((element) => {
      const key = element.getAttribute('data-i18n');
      if (!key) return;

      const translatedText = translations[key];
      if (translatedText) {
        // Update text content
        if (element.childNodes.length > 0) {
          // Find and update text nodes
          const walker = document.createTreeWalker(
            element,
            NodeFilter.SHOW_TEXT,
            null
          );

          let textNode = walker.nextNode();
          if (textNode && textNode.nodeValue?.trim()) {
            textNode.nodeValue = translatedText;
          }
        } else {
          element.textContent = translatedText;
        }
      }
    });
  }

  /**
   * Switch to a different language
   */
  async switchLanguage(language: string): Promise<void> {
    if (language === this.currentLanguage) {
      return; // Already on this language
    }

    // Load language if not already loaded
    if (!this.translations.has(language)) {
      await this.loadLanguage(language);
    }

    // Update current language
    this.currentLanguage = language;
    this.saveLanguage(language);

    // Update DOM
    this.updateDOM(language);

    // Dispatch custom event for components that need to react
    if (typeof window !== 'undefined') {
      window.dispatchEvent(
        new CustomEvent('languageChanged', {
          detail: { language }
        })
      );
    }
  }

  /**
   * Get current language
   */
  getCurrentLanguage(): string {
    return this.currentLanguage;
  }

  /**
   * Initialize the language switcher (load current language and update DOM)
   */
  async initialize(): Promise<void> {
    try {
      await this.loadLanguage(this.currentLanguage);
      this.updateDOM(this.currentLanguage);
    } catch (error) {
      console.error('Error initializing language switcher:', error);
    }
  }

  /**
   * Preload multiple languages
   */
  async preloadLanguages(languages: string[]): Promise<void> {
    await Promise.all(
      languages.map(lang => this.loadLanguage(lang).catch(() => {
        // Ignore errors for preloading
      }))
    );
  }
}

// Export singleton instance
let globalInstance: LanguageSwitcher | null = null;

/**
 * Get or create global language switcher instance
 */
export function getLanguageSwitcher(options?: LanguageSwitcherOptions): LanguageSwitcher {
  if (!globalInstance) {
    globalInstance = new LanguageSwitcher(options);
  }
  return globalInstance;
}

/**
 * Switch language using global instance
 */
export async function switchLanguage(language: string): Promise<void> {
  const switcher = getLanguageSwitcher();
  await switcher.switchLanguage(language);
}

/**
 * Get current language from global instance
 */
export function getCurrentLanguage(): string {
  const switcher = getLanguageSwitcher();
  return switcher.getCurrentLanguage();
}

/**
 * Initialize language switcher
 */
export async function initializeI18n(options?: LanguageSwitcherOptions): Promise<void> {
  const switcher = getLanguageSwitcher(options);
  await switcher.initialize();
}
